`timescale 1ns/1ps
// Generated by uvmgen from the verification plan. Do not edit.
module tb;
    logic clk = 1'b0;
    logic rst_n = 1'b0;
    logic tx_valid;
    logic [7:0] tx_data;
    logic tx_ready;
    logic exp_tx_ready;
    bit   chk_tx_ready;
    logic txd;
    logic exp_txd;
    bit   chk_txd;

    uart_tx_buggy #(.CLKS_PER_BIT(4)) dut (.clk(clk), .rst_n(rst_n), .tx_valid(tx_valid), .tx_data(tx_data), .tx_ready(tx_ready), .txd(txd));

    always #5.0 clk = ~clk;

    // ---------------- reference model ----------------
    localparam int C = 4;
    bit m_busy;
    int m_cnt;          // cycles since the frame started (0 = first start-bit cycle)
    logic [7:0] m_data;
    bit m_just_done;    // the previous cycle was the last stop-bit cycle
    bit m_busy_at_reset;
    int m_bit;
    function automatic void m_reset();
        m_busy_at_reset = m_busy;
        m_busy = 0;
        m_cnt = 0;
        m_data = 8'h00;
        m_just_done = 0;
    endfunction
    function automatic void m_outputs();
        chk_tx_ready = 1'b1;
        chk_txd = 1'b1;
        exp_tx_ready = !m_busy;
        if (!m_busy) begin
            exp_txd = 1'b1;
        end else begin
            m_bit = m_cnt / C;                 // 0 start, 1..8 data, 9 stop
            if (m_bit == 0)      exp_txd = 1'b0;
            else if (m_bit <= 8) exp_txd = m_data[m_bit - 1];
            else                 exp_txd = 1'b1;
        end
    endfunction
    function automatic void m_step();
        m_just_done = 0;
        if (!m_busy) begin
            if (tx_valid) begin
                m_busy = 1;
                m_cnt  = 0;
                m_data = tx_data;
            end
        end else begin
            m_cnt = m_cnt + 1;
            if (m_cnt == 10 * C) begin
                m_busy = 0;
                m_just_done = 1;
            end
        end
    endfunction

    // ---------------- sequence variables ----------------
    int i;

    // ---------------- scoreboard + coverage ----------------
    int cov_hits [8];
    int errors = 0, checks = 0, cyc = 0;
    string cur_seq;
    task automatic check();
        m_outputs();
        checks++;
        if (chk_tx_ready && (tx_ready !== exp_tx_ready)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=tx_ready got=%0h exp=%0h | rst_n=%0b tx_valid=%0h tx_data=%0h", cyc, cur_seq, i, tx_ready, exp_tx_ready, rst_n, tx_valid, tx_data);
        end
        if (chk_txd && (txd !== exp_txd)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=txd got=%0h exp=%0h | rst_n=%0b tx_valid=%0h tx_data=%0h", cyc, cur_seq, i, txd, exp_txd, rst_n, tx_valid, tx_data);
        end
        if (tx_valid && tx_ready) cov_hits[0]++;
        if (tx_valid && tx_ready && tx_data == 8'h00) cov_hits[1]++;
        if (tx_valid && tx_ready && tx_data == 8'hFF) cov_hits[2]++;
        if (tx_valid && tx_ready && tx_data == 8'h55) cov_hits[3]++;
        if (tx_valid && tx_ready && tx_data == 8'hAA) cov_hits[4]++;
        if (tx_valid && !tx_ready) cov_hits[5]++;
        if (tx_valid && tx_ready && m_just_done) cov_hits[6]++;
        if (rst_n == 1'b0 && m_busy_at_reset) cov_hits[7]++;
    endtask

    task automatic drive_defaults();
        tx_valid = 1'b0;
        tx_data = 8'h00;
    endtask

    initial begin
        drive_defaults();
        rst_n = 1'b0;
        m_reset();
        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        // sequence: random_frames
        cur_seq = "random_frames";
        for (i = 0; i < 4000; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            tx_valid = 1'($urandom_range(0, 3) == 0);
            tx_data = 8'($urandom);
            rst_n = 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        // sequence: patterns_back_to_back
        cur_seq = "patterns_back_to_back";
        for (i = 0; i < 328; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            tx_valid = 1'b1;
            tx_data = ((i / 41) % 4 == 0) ? 8'h00 : ((i / 41) % 4 == 1) ? 8'hFF : ((i / 41) % 4 == 2) ? 8'h55 : 8'hAA;
            rst_n = 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        // sequence: reset_mid_frame
        cur_seq = "reset_mid_frame";
        for (i = 0; i < 300; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            tx_valid = 1'($urandom_range(0, 1));
            tx_data = 8'($urandom);
            rst_n = ((i % 100) == 17 || (i % 100) == 18) ? 1'b0 : 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        $display("COVER frame_accepted %0d", cov_hits[0]);
        $display("COVER data_0x00 %0d", cov_hits[1]);
        $display("COVER data_0xff %0d", cov_hits[2]);
        $display("COVER data_0x55 %0d", cov_hits[3]);
        $display("COVER data_0xaa %0d", cov_hits[4]);
        $display("COVER request_while_busy %0d", cov_hits[5]);
        $display("COVER back_to_back %0d", cov_hits[6]);
        $display("COVER reset_mid_frame %0d", cov_hits[7]);
        $display("CHECKS %0d ERRORS %0d", checks, errors);
        if (errors == 0) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
